mapper.select:
SELECT T4.BUSI_ACCT_NO id, T4.ACCT_NAME text FROM MST_COUNTER_PARTY T1 LEFT JOIN FIN_PRODUCT T2 ON T1.LINK_ID = T2.FINPROD_ID LEFT JOIN STL_FIN_PRODUCT_ACCT T3 ON T3.FINPROD_ID = T2.FINPROD_ID LEFT JOIN STL_CAPACCT_INFO T4 ON T4.ACCT_NO = T3.ACCT_NO
AND T4.BUSI_ACCT_NO = #{initValue}
AND COUNTER_ID = #{counterId,jdbcType=VARCHAR}
